$ErrorActionPreference = 'Stop'; $temp=Join-Path $env:TEMP "installer-fresh-$PID"; $dist=Join-Path $temp 'dist'; New-Item -ItemType Directory -Force $dist | Out-Null; $sentinel=Join-Path $temp 'sentinel'; Set-Content $sentinel 'start'; foreach($name in @('Dim-Sum-Atlas-0.1.1-win-x64.exe','RELEASES','dim-sum-atlas-0.1.1-full.nupkg','installer-manifest.json')){Set-Content (Join-Path $dist $name) 'old'}; (Get-Item $sentinel).LastWriteTimeUtc=(Get-Date).ToUniversalTime().AddSeconds(1); & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot 'assert-installer-fresh.ps1') -Sentinel $sentinel -Dist $dist | Out-Null; $red=($LASTEXITCODE -ne 0); if(-not $red){throw 'Stale artifacts were accepted.'}; Start-Sleep -Milliseconds 1100; foreach($name in @('Dim-Sum-Atlas-0.1.1-win-x64.exe','RELEASES','dim-sum-atlas-0.1.1-full.nupkg','installer-manifest.json')){(Get-Item (Join-Path $dist $name)).LastWriteTimeUtc=(Get-Date).ToUniversalTime()}; & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot 'assert-installer-fresh.ps1') -Sentinel $sentinel -Dist $dist | Out-Null; if($LASTEXITCODE -ne 0){throw 'Fresh artifacts were rejected.'}; Remove-Item $temp -Recurse -Force; Write-Output 'PASS stale installer freshness regression'
